import { describe, expect, it } from 'vitest';
import sampleForms from '../test-vectors/sample-forms.json' with { type: 'json' };
import sampleIndex from '../test-vectors/sample-index.json' with { type: 'json' };
import { SymbolSearch, type SearchOptions } from './search.ts';
import { LexiconSchema, SymbolIndexSchema, type SymbolIndex } from './symbols.ts';

// Generated by tools/tests (UPDATE_GOLDEN=1 uv run pytest): the Python writer and the
// TypeScript reader must agree on the format.
const arasaac = SymbolIndexSchema.parse(sampleIndex);
const forms = LexiconSchema.parse(sampleForms);

const extra: SymbolIndex = {
  v: 1,
  set: 'extra',
  name: 'Dodatkowy',
  items: [
    { id: 1, f: 'x/1.0000abcd.webp', k: ['jabłko'], r: 'noun', c: 'Jedzenie' },
    { id: 2, f: 'x/2.0000abcd.webp', k: ['seks'], r: 'noun', x: 2 },
  ],
};

const ALL: SearchOptions = { sets: ['arasaac', 'extra'], hideSexual: true, hideViolence: true };
const search = new SymbolSearch([arasaac, extra], [forms]);
const ids = (query: string, options: SearchOptions = ALL) =>
  search.search(query, options).map((hit) => `${hit.set}:${hit.id}`);

describe('shared vectors', () => {
  it('Python-built index and lexicon pass the client schemas', () => {
    expect(arasaac.items.length).toBe(11);
    expect(Object.keys(forms.lemmas)).toContain('jablko');
  });
});

describe('SymbolSearch', () => {
  it('finds inflected forms typed without Polish characters (F1 acceptance)', () => {
    const hits = search.search('jablka', ALL);
    expect(hits[0]).toMatchObject({ set: 'arasaac', id: 2462, label: 'jabłko', role: 'noun' });
    expect(hits[0]!.src).toMatch(/^\/sym\/arasaac\/p\/2462\.[0-9a-f]{8}\.webp$/);
    expect(hits.map((h) => `${h.set}:${h.id}`).slice(0, 2)).toEqual(['arasaac:2462', 'extra:1']);
  });

  it('matches inflected words inside multi-word keywords', () => {
    expect(ids('jabłko')).toContain('arasaac:9057'); // "ciasto z jabłkami"
    const hit = search.search('jablko', ALL).find((h) => h.id === 9057)!;
    expect(hit.label).toBe('ciasto z jabłkami');
  });

  it('ranks exact whole-keyword matches above longer keywords', () => {
    const list = ids('ciasto');
    expect(list[0]).toBe('arasaac:9057');
    expect(search.search('ciasto', ALL)[0]!.label).toBe('ciasto');
  });

  it('lemmatizes verbs: "piłem" → pić', () => {
    expect(ids('pilem')).toEqual(['arasaac:6061']);
    expect(ids('Piję')).toEqual(['arasaac:6061']);
  });

  it('requires every query word to match', () => {
    expect(ids('dzień dobry')).toEqual(['arasaac:7000']);
    expect(ids('dnia dobrego')).toEqual(['arasaac:7000']);
    expect(ids('dzień kot')).toEqual([]);
  });

  it('type-ahead matches the last word as a prefix, but not after a space', () => {
    expect(ids('jab')).toEqual(expect.arrayContaining(['arasaac:2462', 'arasaac:11403']));
    expect(ids('jab ')).toEqual([]);
    expect(ids('j')).toEqual([]); // too short for a prefix
  });

  it('ignores punctuation and case', () => {
    expect(ids('CO')).toEqual(['arasaac:7002']);
    expect(ids('  ola!! ')).toEqual(['arasaac:7001']);
  });

  it('respects active sets and their priority', () => {
    expect(ids('jablko', { ...ALL, sets: ['extra'] })).toEqual(['extra:1']);
    expect(ids('jablko', { ...ALL, sets: ['extra', 'arasaac'] }).slice(0, 2)).toEqual([
      'extra:1',
      'arasaac:2462',
    ]);
    expect(ids('jablko', { ...ALL, sets: [] })).toEqual([]);
  });

  it('hides sexual and violent content unless the filter is off', () => {
    expect(ids('całować')).toEqual([]);
    expect(ids('bić')).toEqual([]);
    expect(ids('seks')).toEqual([]);
    const open = { ...ALL, hideSexual: false, hideViolence: false };
    expect(ids('całować', open)).toEqual(['arasaac:5000']);
    expect(ids('bić', open)).toEqual(['arasaac:5001']);
    expect(ids('seks', open)).toEqual(['extra:2']);
  });

  it('prefers AAC core vocabulary on equal matches', () => {
    // Both "nos" pictograms match exactly; neither is AAC, so the older id wins.
    expect(ids('nos')).toEqual(['arasaac:2727', 'arasaac:30000']);
    const aac = new SymbolSearch([
      { ...arasaac, items: arasaac.items.map((i) => (i.id === 30000 ? { ...i, x: 1 } : i)) },
    ]);
    expect(aac.search('nos', ALL).map((h) => h.id)).toEqual([30000, 2727]);
  });

  it('works without a lexicon (exact words only)', () => {
    const plain = new SymbolSearch([arasaac]);
    expect(plain.search('jablka ', ALL)).toEqual([]); // no lemma; prefix of "jabłkami" only while typing
    expect(plain.search('jablko', ALL)[0]!.id).toBe(2462);
  });

  it('returns nothing for empty or punctuation-only queries', () => {
    expect(ids('')).toEqual([]);
    expect(ids('?!')).toEqual([]);
  });

  it('caps the number of results', () => {
    expect(search.search('jab', { ...ALL, limit: 1 })).toHaveLength(1);
  });

  it('carries the extra set category for display', () => {
    expect(search.search('jablko', { ...ALL, sets: ['extra'] })[0]!.category).toBe('Jedzenie');
  });
});
